    n += put(g, cx, 2, cz, B.trapdoor("birch", facing, "top", false));
    n += put(g, cx, 3, cz, B.slab("birch", "bottom"));
    if (i === mid) n += put(g, cx, 4, cz, B.block("potted_cactus"));
  }
  return n;
}

